SC.searching=()=>{const tot=2*parseInt(S.match.fmt);const{A,B}=teams();const all=[];A.forEach((a,i)=>{all.push(a);if(B[i])all.push(B[i])});return`<div class="scr center">
<div class="radar"><div class="st1"></div><div class="st2"></div><div class="sweep"></div><div class="ring"></div><div class="ring"></div><div class="ring"></div><div class="core">${logoMark(64)}</div>
${all.map((p,i)=>{const a=(i/tot)*Math.PI*2-Math.PI/2,r=i%2?78:122;return`<div class="rav" id="rav${i}" style="left:${140+r*Math.cos(a)-17}px;top:${140+r*Math.sin(a)-17}px">${av(p.n,34,p.c,p.you?'box-shadow:0 0 0 2px #3ddc84':'')}</div>`}).join('')}</div>
<div class="count"><b id="sc">0</b><span>/${tot} ${t('players_n')}</span></div>
<h1 class="t">${t('searching')}</h1>
<ul class="steps">${[1,2,3,4].map(i=>`<li class="step" id="step${i}"><i>${ic('check',13)}</i>${t('s'+i)}</li>`).join('')}</ul>
<button class="ghost" data-act="tab" data-arg="play">${t('cancel_search')}</button>
</div>`};

SC.found=()=>{const m=S.match,s=ST[m.st];const{A,B,size,avgA,avgB}=teams();const FA=A.filter(p=>p.friend);const W=350,H=176;const X={GK:.06,DEF:.2,MID:.33,FWD:.44};
const dots=(T,side)=>{const g={};T.forEach((p,i)=>{(g[p.p]=g[p.p]||[]).push(i)});return T.map((p,i)=>{const line=g[p.p],k=line.indexOf(i);let x=X[p.p]*W;if(side==='B')x=W-x;const y=(k+1)/(line.length+1)*H;const col=side==='A'?'#3ddc84':'#ef7b5a';return`<g class="pd" id="pd${side}${i}"><circle cx="${x}" cy="${y}" r="${p.you?13:11}" fill="${p.you?col:'#06110b'}" stroke="${col}" stroke-width="2"/><text x="${x}" y="${y+.5}" text-anchor="middle" dominant-baseline="middle" fill="${p.you?'#04200f':col}" font-size="8" font-weight="800" font-family="Cairo">${t('pos_'+p.p)}</text></g>`}).join('')};
const circ=2*Math.PI*42;
return`<div class="scr found pb-foot">
<div class="f-top"><span class="eyebrow">${ic('bolt',14)}${t('found')}</span><h1 class="t">${L(s.n)}</h1><div class="meta c">${dayLabel(m.day)} · <b class="num">${m.time}</b> · ${m.fmt} · ${t('each',{p:ppp(m.st,m.fmt)})}</div></div>
<div class="f-row"><div class="cd"><svg width="96" height="96" viewBox="0 0 96 96" style="transform:rotate(-90deg)"><circle cx="48" cy="48" r="42" fill="none" stroke="#132a1d" stroke-width="7"/><circle id="cda" cx="48" cy="48" r="42" fill="none" stroke="#3ddc84" stroke-width="7" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="0" style="transition:stroke-dashoffset 1s linear,stroke .3s"/></svg><div class="cd-n"><b id="cdn">30</b><span>${t('sec')}</span></div></div>
<div class="f-info"><div class="meta">${t('accept_within')}</div>${FA.length?`<div class="row g8" style="margin-top:8px"><div class="stack">${FA.slice(0,3).map(p=>av(p.n,26,p.c)).join('')}</div><span class="fr">${FA.slice(0,2).map(p=>'@'+p.h).join(', ')}${FA.length>2?' +'+(FA.length-2):''} · ${t('same_team')}</span></div>`:''}<div class="meta" style="margin-top:6px">⚖️ ${t('balanced')} · <b class="num">${num(avgA)}</b> vs <b class="num">${num(avgB)}</b></div>${S.prefs.ref?`<div class="meta">🟨 ${t('referee')}: <b>@karim_ref</b></div>`:''}</div></div>
<div class="fpitch turf">${pitchLines(W,H,.32)}<svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" style="position:absolute;inset:0">${dots(A,'A')}${dots(B,'B')}</svg></div>
<div class="teams">${[[A,'A',t('your_team'),'var(--lime)'],[B,'B',t('opponents'),'var(--terra)']].map(([T,sd,lb,col])=>`<div><h3 style="color:${col}">${lb}</h3>${T.map((p,i)=>`<div class="pr" id="pr${sd}${i}">${av(p.n,24,p.c)}<span class="re">${rankOf(p.you?1240:600+((p.c*337)%1700))[1]}</span><span class="${p.you?'you':''}">@${p.h}${p.you?` (${t('you')})`:''}</span><span class="pos">${POS_E[p.p]}</span></div>`).join('')}</div>`).join('')}</div>
</div>
<div class="foot"><div class="row g10"><button class="ghost" data-act="pass">${t('pass')}</button><button class="cta" style="flex:1" data-act="accept">${ic('bolt',20)}${t('accept')}</button></div></div>`};

const codeOf=m=>'MTK-'+(m.st*7+3)+String.fromCharCode(65+m.st)+'-'+m.time.replace(':','');
const ticket=m=>{const s=ST[m.st];return`<div class="ticket"><div class="qrbox">${qr(codeOf(m))}</div><div class="code"><small>${t('code')}</small><b>${codeOf(m)}</b></div><div class="perf"></div><div class="kv"><span>${t('pitch')}</span><b>${L(s.n)}</b></div><div class="kv"><span>${t('when')}</span><b>${dayLabel(m.day)} · ${m.time}</b></div><div class="kv"><span>${t('format')}</span><b>${m.fmt}</b></div><div class="kv"><span>${t('per_player')}</span><b>${num(ppp(m.st,m.fmt))} ${t('da')}</b></div></div>`};

SC.confirmed=()=>`<div class="scr pb-foot"><div class="center" style="padding-top:18px"><div class="ok">${ic('check',32)}</div><h1 class="disp">${t('in')}</h1><p class="meta c" style="max-width:260px">${t('in_sub')}</p></div><div class="pad mt16"><div class="card">${ladder('confirmed')}</div></div>${ticket(S.match)}</div>
<div class="foot"><button class="cta" data-act="tab" data-arg="matches">${t('go_matches')}</button></div>`;

const PAST=[{st:2,day:-3,time:'20:00',fmt:'5v5',score:'6 – 4',res:'win'},{st:0,day:-6,time:'21:00',fmt:'6v6',score:'3 – 5',res:'loss'},{st:1,day:-9,time:'19:00',fmt:'8v8',score:'4 – 4',res:'draw'}];
SC.matches=()=>{const up=[];if(S.joined)up.push({...S.joined,status:'ok'});up.push({st:1,day:1,time:'19:00',fmt:'8v8',status:'pend'});
const dblock=d=>`<div class="date"><small>${wd(d)}</small><b>${dayDate(d).getDate()}</b></div>`;
return`<div class="scr"><header class="ptitle"><h1 class="disp">${t('nav_matches')}</h1></header>
<div class="pad"><div class="seg">${['upcoming','past'].map(k=>`<button class="${S.mtab===k?'on':''}" data-act="mtab" data-arg="${k}">${t(k)}</button>`).join('')}</div></div>
<div class="list mt16">${S.mtab==='upcoming'?up.map((m,i)=>`<div class="mcard">${dblock(m.day)}<div class="info"><div class="name">${L(ST[m.st].n)}</div><div class="meta"><b class="num">${m.time}</b> · ${m.fmt}</div><span class="tag ${m.status==='ok'?'':'pend'}">${m.status==='ok'?t('confirmed'):t('pending')}</span></div>${m.status==='ok'?`<button class="iconbtn lime" data-act="qr" data-arg="${i}">${ic('qr',20)}</button>`:''}</div>`).join(''):PAST.map((m,i)=>`<div class="mcard">${dblock(m.day)}<div class="info"><div class="name">${L(ST[m.st].n)}</div><div class="meta">${m.fmt} · <span class="res ${m.res}">${t(m.res)}</span></div></div><div class="endcol"><b class="score">${m.score}</b>${S.rated[i]?`<span class="meta">${ic('check',13)}${t('rated')}</span>`:`<button class="btn-sm" data-act="rate" data-arg="${i}">${t('rate')}</button>`}</div></div>`).join('')}</div></div>
${S.sheet==='qr'?`<div class="overlay" data-act="close"><div class="sheet" data-act="noop"><div class="grab"></div>${ticket(S.joined)}<button class="ghost w" data-act="close">${ic('x',18)}</button></div></div>`:''}
${S.sheet==='rate'?`<div class="overlay" data-act="close"><div class="sheet" data-act="noop"><div class="grab"></div><h2 class="t2">${t('rate_title')}</h2><div class="meta">${L(ST[PAST[S.rateIdx].st].n)} · ${t('rate_pitch')}</div><div class="rstars">${[1,2,3,4,5].map(n=>`<button class="${S.rateStars>=n?'on':''}" data-act="rstar" data-arg="${n}">${ic('star',34)}</button>`).join('')}</div><div class="row g6 wrap">${['#new_turf','#great_lights','#clean','#fair_play','#on_time','#old_ball'].map(x=>`<button class="chip ${S.rateTags.includes(x)?'on':''}" data-act="rtag" data-arg="${x}">${x}</button>`).join('')}</div><button class="cta mt16 ${S.rateStars?'':'disabled'}" data-act="${S.rateStars?'rsubmit':'noop'}">${t('submit')} · ${t('earn')}</button></div></div>`:''}`};

SC.profile=()=>`<div class="scr"><header class="ptitle"><h1 class="disp">${t('nav_profile')}</h1><button class="iconbtn" data-act="go" data-arg="settings">${ic('gear',20)}</button></header>
<section class="pcard zel"><div class="row g14"><div style="position:relative">${av('Amine B',72,0)}<span class="verif">${ic('check',12)}</span></div><div><div class="name lg">Amine Benali</div><div style="margin:3px 0">${verBadge()}</div><div class="meta">@amineB7 · ${rankBadge('gold')}</div><div class="row g6 wrap" style="margin-top:8px">${posBadge('MID')}${posBadge('FWD')}</div></div></div>
<div class="toks"><div><small>${t('points')}</small><b>1 240</b></div><div><small>${t('tokens')}</small><b>${S.rt} RT</b></div></div></section>
<div class="stats">${[['47',t('played')],['28',t('wins')],['94%',t('reliability')]].map(([v,l])=>`<div class="stat"><b>${v}</b><span>${l}</span></div>`).join('')}</div>
<div class="pad">${(()=>{const me=1240,r=rankOf(me),nx=RANKS[RANKS.indexOf(r)+1];return`<div class="card mt16"><div class="row sb"><div class="row g10"><span class="remo">${r[1]}</span><div><div class="meta">${t('rank')}</div>${rankBadge(r[0])}</div></div><div class="endcol"><span class="meta">${nx[1]} ${t('rank_'+nx[0])}</span><b class="num">${num(me)} / ${num(nx[2])}</b></div></div><div class="bar gold"><i style="width:${(me-r[2])/(nx[2]-r[2])*100}%"></i></div><div class="meta">${t('to_next',{n:num(nx[2]-me),r:t('rank_'+nx[0])})}</div></div>`})()}<div class="card mt16"><div class="row sb"><b>${t('reliability')}</b><b class="num" style="color:var(--lime)">94%</b></div><div class="bar"><i style="width:94%"></i></div><div class="meta">${t('rel_sub')}</div></div>
<h2 class="mt">${t('teams')}</h2>
${[['FC El Harrach',6,'captain','12 – 8'],['Amis du Mercredi',8,'member','7 – 5']].map(([n,m,r,rec],i)=>`<div class="mcard mb">${`<span class="crest">${logoMark(26)}</span>`}<div class="info"><div class="name">${n}</div><div class="meta">${t('members',{n:m})} · ${t(r)}</div></div><b class="score sm">${rec}</b></div>`).join('')}
</div></div>`;

SC.settings=()=>`<div class="scr"><header class="ptitle"><div class="row g10"><button class="iconbtn" data-act="tab" data-arg="profile">${ic('back',20,'flip')}</button><h1 class="t">${t('settings')}</h1></div></header>
<div class="pad"><div class="glabel">${ic('globe',15)}${t('language')}</div><div class="group">${[['en','English','EN'],['fr','Français','FR'],['ar','العربية','ع']].map(([k,n,c])=>`<button class="opt" data-act="lang" data-arg="${k}"><span class="lcode">${c}</span><b>${n}</b><span class="radio ${S.lang===k?'on':''}"></span></button>`).join('')}</div>
<div class="glabel">${ic('bell',15)}${t('notifs')}</div><div class="group">${[['alerts','alerts_sub'],['reminders','reminders_sub']].map(([k,s])=>`<button class="opt" data-act="toggle" data-arg="${k}"><div style="flex:1"><b>${t(k)}</b><div class="meta">${t(s)}</div></div><span class="sw ${S[k]?'on':''}"></span></button>`).join('')}</div></div></div>`;
